-- Starting assignment of existing questions to submodules, so answer explanations can show a Skill Jar link.
-- Domains with one submodule: every question goes there. Domains with two: the sub-skills listed in step 1 go to the
-- second course, everything else to the first. This is a starting guess; reassign any question in the question bank.
-- Generated by scripts/generate-submodule-seed-sql.ts. Only fills questions with no submodule yet. Safe to re-run.

-- 1. Specific sub-skills
with rule(track, domain, section, submodule) as (values
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$MCP Server Development$q$, $q$Claude Code, MCP & Integration$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Configuration Management$q$, $q$Accelerators & IP Contribution$q$)
)
update quiz_questions qq
set submodule_id = sm.id
from rule r
join quiz_modules m on m.title = r.domain and m.track = r.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = r.submodule
where qq.module_id = m.id and qq.section = r.section and qq.submodule_id is null;

-- 2. Everything else in the domain goes to its first submodule
with dflt(track, domain, submodule) as (values
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Claude Platform & Model Foundations$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$Prompting & Task Execution$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Evaluating & Validating Claude's Output$q$),
  ($q$associate$q$, $q$Workflow Integration and Solution Design$q$, $q$Workflow Integration & Solution Design$q$),
  ($q$associate$q$, $q$Configuration and Knowledge Management$q$, $q$Configuration & Knowledge Management$q$),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$Governance, Risk & Responsible Use$q$),
  ($q$associate$q$, $q$Troubleshooting and Optimization$q$, $q$Troubleshooting & Optimization$q$),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$MSO Foundations$q$),
  ($q$developer$q$, $q$Prompt and Context Engineering$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$),
  ($q$developer$q$, $q$Agents and Workflows$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code, MCP & Integration$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$),
  ($q$developer$q$, $q$Security and Safety$q$, $q$Production Engineering, Evals & Security$q$),
  ($q$developer$q$, $q$Eval, Testing, and Debugging$q$, $q$Production Engineering, Evals & Security$q$)
)
update quiz_questions qq
set submodule_id = sm.id
from dflt d
join quiz_modules m on m.title = d.domain and m.track = d.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = d.submodule
where qq.module_id = m.id and qq.submodule_id is null;

-- Check: questions per submodule
select m.track, m.title as domain, sm.title as submodule, count(qq.id) as questions
from quiz_submodules sm
join quiz_modules m on m.id = sm.module_id
left join quiz_questions qq on qq.submodule_id = sm.id
group by m.track, m.title, sm.title, sm.order_index
order by m.track, m.title, sm.order_index;
